1	// Package review — see env.go for package-level rationale.
2	//
3	// tui_model.go provides reviewTUIModel, the Bubble Tea Model for the
4	// review dashboard. The model renders a per-agent status table
5	// during the run and supports Ctrl+O drill-in mode for inspecting one agent's
6	// live event buffer on the alt screen.
7	package review
8	
9	import (
10		"context"
11		"fmt"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16	
17		"charm.land/bubbles/v2/spinner"
18		tea "charm.land/bubbletea/v2"
19		"charm.land/lipgloss/v2"
20	
21		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
22		"github.com/entireio/cli/cmd/entire/cli/stringutil"
23	)
24	
25	// agentRow holds per-agent live state during the TUI run.
26	type agentRow struct {
27		name     string
28		status   reviewtypes.AgentStatus
29		runStart time.Time          // stamped on first event from this agent
30		runEnd   time.Time          // stamped on Finished/RunError event
31		tokens   reviewtypes.Tokens // cumulative
32		preview  string             // latest AssistantText preview, capped by display width
33		buffer   []reviewtypes.Event
34		err      error
35	}
36	
37	// agentEventMsg is sent to the Bubble Tea program when an agent emits an event.
38	type agentEventMsg struct {
39		agent string
40		ev    reviewtypes.Event
41	}
42	
43	// runFinishedMsg is sent when the orchestrator calls RunFinished.
44	type runFinishedMsg struct {
45		summary reviewtypes.RunSummary
46	}
47	
48	// tickMsg triggers spinner and duration column updates.
49	type tickMsg time.Time
50	
51	// reviewTUIModel is the Bubble Tea model for the review dashboard.
52	type reviewTUIModel struct {
53		rows         []agentRow
54		rowIdx       map[string]int // agent name → row index (O(1) lookup)
55		detailMode   bool
56		detailIdx    int // which agent is shown in drill-in
57		detailScroll int
58	
59		cancel     context.CancelFunc
60		cancelOnce *sync.Once
61	
62		spinner    spinner.Model
63		termWidth  int
64		termHeight int
65	
66		finished bool
67		summary  reviewtypes.RunSummary
68	}
69	
70	// newReviewTUIModel builds an initial model pre-populated with one row per
71	// agent. cancel is the shared CancelFunc; it must be the same one passed to
72	// NewTUISink.
73	func newReviewTUIModel(agents []string, cancel context.CancelFunc) reviewTUIModel {
74		sp := spinner.New()
75		sp.Spinner = spinner.Dot
76		sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
77	
78		rows := make([]agentRow, len(agents))
79		rowIdx := make(map[string]int, len(agents))
80		for i, name := range agents {
81			rows[i] = agentRow{
82				name:   name,
83				status: reviewtypes.AgentStatusUnknown,
84			}
85			rowIdx[name] = i
86		}
87		return reviewTUIModel{
88			rows:       rows,
89			rowIdx:     rowIdx,
90			cancel:     cancel,
91			cancelOnce: &sync.Once{},
92			spinner:    sp,
93			termWidth:  80,
94			termHeight: 24,
95		}
96	}
97	
98	// tickCmd schedules the next tick for duration/spinner refresh.
99	func tickCmd() tea.Cmd {
100		return tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg {
101			return tickMsg(t)
102		})
103	}
104	
105	// Init returns the initial spinner tick command.
106	func (m reviewTUIModel) Init() tea.Cmd {
107		return tea.Batch(m.spinner.Tick, tickCmd())
108	}
109	
110	// Update handles all incoming messages.
111	func (m reviewTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
112		switch msg := msg.(type) {
113		case agentEventMsg:
114			return m.handleAgentEvent(msg)
115	
116		case runFinishedMsg:
117			m.finished = true
118			m.summary = msg.summary
119			// Sync each row's status from the orchestrator's summary. The
120			// in-stream events (Finished / RunError) update status as they
121			// arrive, but the orchestrator's classifyStatus has access to
122			// process-level signals (Wait error, ctx cancellation) that the
123			// event stream never surfaces. Without this sync, an agent that
124			// the orchestrator classified Cancelled (Ctrl+C path, no Finished
125			// emitted) or Failed (process exit non-zero, no Finished emitted)
126			// would still render as "running" in the final frame.
127			//
128			// Preserve any already-set status from the event stream — if the
129			// stream said Failed (RunError), the summary may say Succeeded
130			// (process exit 0); RunError stickiness wins. Only overwrite when
131			// the row is still in AgentStatusUnknown.
132			now := time.Now()
133			for i, run := range msg.summary.AgentRuns {
134				if i >= len(m.rows) {
135					break
136				}
137				if m.rows[i].status == reviewtypes.AgentStatusUnknown {
138					m.rows[i].status = run.Status
139				}
140				if m.rows[i].runEnd.IsZero() && !m.rows[i].runStart.IsZero() {
141					m.rows[i].runEnd = now
142				}
143			}
144			return m, nil
145	
146		case tickMsg:
147			var spinCmd tea.Cmd
148			m.spinner, spinCmd = m.spinner.Update(msg)
149			return m, tea.Batch(spinCmd, tickCmd())
150	
151		case spinner.TickMsg:
152			var spinCmd tea.Cmd
153			m.spinner, spinCmd = m.spinner.Update(msg)
154			return m, spinCmd
155	
156		case tea.WindowSizeMsg:
157			m.termWidth = msg.Width
158			m.termHeight = msg.Height
159			m = m.clampScroll()
160			return m, nil
161	
162		case tea.KeyPressMsg:
163			return m.handleKey(msg)
164		}
165		return m, nil
166	}
167	
168	// handleAgentEvent processes an agentEventMsg, updating the relevant row.
169	func (m reviewTUIModel) handleAgentEvent(msg agentEventMsg) (tea.Model, tea.Cmd) {
170		idx, ok := m.rowIdx[msg.agent]
171		if !ok {
172			return m, nil
173		}
174		row := &m.rows[idx]
175	
176		// Stamp run-start on the first event from this agent (per-row, not
177		// TUI-start; prevents inflated durations for late-starting agents).
178		if row.runStart.IsZero() {
179			row.runStart = time.Now()
180		}
181	
182		row.buffer = append(row.buffer, msg.ev)
183	
184		switch e := msg.ev.(type) {
185		case reviewtypes.Started:
186			// runStart already set; no other state update needed.
187		case reviewtypes.AssistantText:
188			collapsed := stringutil.CollapseWhitespace(sanitizeDisplayText(e.Text))
189			row.preview = truncateDisplayWidth(collapsed, 80)
190		case reviewtypes.Tokens:
191			row.tokens = e // cumulative: overwrite, not sum
192		case reviewtypes.Finished:
193			// RunError is sticky: if a prior RunError event already classified
194			// this row as Failed, a subsequent Finished{Success: true} must NOT
195			// flip it back to Succeeded. CU3's parser-fix-loop guarantees that
196			// RunError + Finished{Success:false} both accompany torn streams;
197			// matching that contract here keeps the TUI consistent with
198			// classifyStatus from CU4 (which honors sawRunError).
199			if row.status != reviewtypes.AgentStatusFailed {
200				if e.Success {
201					row.status = reviewtypes.AgentStatusSucceeded
202				} else {
203					row.status = reviewtypes.AgentStatusFailed
204				}
205			}
206			row.runEnd = time.Now()
207		case reviewtypes.RunError:
208			row.status = reviewtypes.AgentStatusFailed
209			row.err = e.Err
210			if row.runEnd.IsZero() {
211				row.runEnd = time.Now()
212			}
213		case reviewtypes.ToolCall:
214			// No visible state update for tool calls in the dashboard.
215		}
216	
217		// Auto-follow ONLY when the user is already at the bottom. This lets a
218		// user scroll up to inspect older events without each new event yanking
219		// them back to the tail. The pre-append max-scroll was for buffer
220		// length-1; if detailScroll was at-or-past that, the user was tailing.
221		if m.detailMode && m.detailIdx == idx {
222			preAppendMax := len(row.buffer) - 2 // -1 for the just-appended event, -1 for max-index
223			if preAppendMax < 0 || m.detailScroll >= preAppendMax {
224				m.detailScroll = m.maxDetailScroll()
225			}
226		}
227	
228		return m, nil
229	}
