231	// handleKey processes keyboard input.
232	func (m reviewTUIModel) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
233		// Any key after finished dismisses.
234		if m.finished {
235			return m, tea.Quit
236		}
237	
238		switch {
239		case msg.Code == 'c' && msg.Mod == tea.ModCtrl:
240			if m.detailMode {
241				// In drill-in: Ctrl+C is intentionally ignored; Esc first.
242				return m, nil
243			}
244			m.cancelOnce.Do(m.cancel)
245			return m, tea.Quit
246	
247		case msg.Code == 'o' && msg.Mod == tea.ModCtrl:
248			if m.detailMode {
249				m.detailMode = false
250				return m, nil
251			}
252			m.detailMode = true
253			if len(m.rows) > 0 && (m.detailIdx < 0 || m.detailIdx >= len(m.rows)) {
254				m.detailIdx = 0
255			}
256			m.detailScroll = m.maxDetailScroll()
257			return m, nil
258	
259		case msg.Code == tea.KeyEscape || msg.Code == tea.KeyEsc:
260			if m.detailMode {
261				m.detailMode = false
262				return m, nil
263			}
264			return m, nil
265	
266		case msg.Code == tea.KeyLeft:
267			if m.detailMode && len(m.rows) > 0 {
268				m.detailIdx = (m.detailIdx - 1 + len(m.rows)) % len(m.rows)
269				m.detailScroll = m.maxDetailScroll()
270			}
271			return m, nil
272	
273		case msg.Code == tea.KeyRight:
274			if m.detailMode && len(m.rows) > 0 {
275				m.detailIdx = (m.detailIdx + 1) % len(m.rows)
276				m.detailScroll = m.maxDetailScroll()
277			}
278			return m, nil
279	
280		case msg.Code == tea.KeyUp:
281			if m.detailMode && m.detailScroll > 0 {
282				m.detailScroll--
283			}
284			return m, nil
285	
286		case msg.Code == tea.KeyDown:
287			if m.detailMode {
288				if maxScroll := m.maxDetailScroll(); m.detailScroll < maxScroll {
289					m.detailScroll++
290				}
291			}
292			return m, nil
293		}
294	
295		return m, nil
296	}
297	
298	// maxDetailScroll returns the largest valid detailScroll value for the current
299	// agent's buffer (0 when the buffer is empty or no rows exist).
300	func (m reviewTUIModel) maxDetailScroll() int {
301		if len(m.rows) == 0 {
302			return 0
303		}
304		n := len(m.rows[m.detailIdx].buffer)
305		if n == 0 {
306			return 0
307		}
308		return n - 1
309	}
310	
311	// clampScroll returns a copy of m with detailScroll clamped to valid bounds.
312	// Used after resize or index change.
313	func (m reviewTUIModel) clampScroll() reviewTUIModel {
314		maxScroll := m.maxDetailScroll()
315		if m.detailScroll > maxScroll {
316			m.detailScroll = maxScroll
317		}
318		return m
319	}
