321	// View renders the current state.
322	func (m reviewTUIModel) View() tea.View {
323		var content string
324		if m.detailMode && len(m.rows) > 0 {
325			content = detailView(m.rows[m.detailIdx], m.detailScroll, m.termWidth, m.termHeight)
326		} else {
327			content = m.dashboardView()
328		}
329		v := tea.NewView(content)
330		v.AltScreen = m.detailMode
331		return v
332	}
333	
334	// dashboardView renders the summary table.
335	func (m reviewTUIModel) dashboardView() string {
336		var b strings.Builder
337	
338		m.writeDashboardLine(&b, m.headerLine())
339	
340		for _, row := range m.rows {
341			m.writeDashboardLine(&b, m.renderRow(row))
342		}
343		b.WriteString("\n")
344	
345		if m.finished {
346			m.writeDashboardLine(&b, m.countsLine())
347			m.writeDashboardLine(&b, "Press any key to exit.")
348		} else {
349			m.writeDashboardLine(&b, "Ctrl+O: drill in · Ctrl+C: cancel")
350		}
351		return b.String()
352	}
353	
354	func (m reviewTUIModel) writeDashboardLine(b *strings.Builder, line string) {
355		b.WriteString(truncateDisplayWidth(line, m.dashboardWidth()))
356		b.WriteString("\n")
357	}
358	
359	func (m reviewTUIModel) dashboardWidth() int {
360		if m.termWidth <= 0 {
361			return 80
362		}
363		return m.termWidth
364	}
365	
366	// headerLine returns the column header row.
367	func (m reviewTUIModel) headerLine() string {
368		return m.renderTableLine("AGENT", "STATUS", "DURATION", "TOKENS", "PREVIEW")
369	}
370	
371	// renderRow renders one agent row.
372	func (m reviewTUIModel) renderRow(row agentRow) string {
373		name := row.name
374	
375		var statusStr string
376		switch row.status {
377		case reviewtypes.AgentStatusSucceeded:
378			statusStr = "✓ done"
379		case reviewtypes.AgentStatusFailed:
380			statusStr = "✗ failed"
381		case reviewtypes.AgentStatusCancelled:
382			statusStr = "— cancel"
383		case reviewtypes.AgentStatusUnknown:
384			if row.runStart.IsZero() {
385				statusStr = "queued"
386			} else {
387				statusStr = m.spinner.View() + " running"
388			}
389		}
390	
391		durStr := ""
392		if !row.runStart.IsZero() {
393			if !row.runEnd.IsZero() {
394				durStr = formatDuration(row.runEnd.Sub(row.runStart))
395			} else {
396				durStr = formatDuration(time.Since(row.runStart))
397			}
398		}
399	
400		tokStr := ""
401		if row.tokens.In > 0 || row.tokens.Out > 0 {
402			tokStr = fmt.Sprintf("%s/%s", formatCompact(row.tokens.In), formatCompact(row.tokens.Out))
403		}
404	
405		return m.renderTableLine(name, statusStr, durStr, tokStr, row.preview)
406	}
407	
408	func (m reviewTUIModel) renderTableLine(agent, status, duration, tokens, preview string) string {
409		const (
410			agentWidth    = 20
411			statusWidth   = 10
412			durationWidth = 8
413			tokensWidth   = 8
414			minWidth      = agentWidth + statusWidth + durationWidth + tokensWidth + 8 // four two-space separators
415		)
416		termWidth := m.dashboardWidth()
417	
418		previewWidth := termWidth - minWidth
419		if previewWidth < 0 {
420			previewWidth = 0
421		}
422	
423		line := fmt.Sprintf("%s  %s  %s  %s  %s",
424			padDisplayWidth(agent, agentWidth),
425			padDisplayWidth(status, statusWidth),
426			padDisplayWidth(duration, durationWidth),
427			padDisplayWidth(tokens, tokensWidth),
428			truncateDisplayWidth(preview, previewWidth))
429		return truncateDisplayWidth(line, termWidth)
430	}
431	
432	// countsLine produces the summary line shown after the run finishes.
433	func (m reviewTUIModel) countsLine() string {
434		succ, fail, canc := 0, 0, 0
435		for _, r := range m.summary.AgentRuns {
436			switch r.Status {
437			case reviewtypes.AgentStatusSucceeded:
438				succ++
439			case reviewtypes.AgentStatusFailed:
440				fail++
441			case reviewtypes.AgentStatusCancelled:
442				canc++
443			case reviewtypes.AgentStatusUnknown:
444				// not counted
445			}
446		}
447		return fmt.Sprintf("%d agent(s) done — %d succeeded, %d failed, %d cancelled",
448			len(m.summary.AgentRuns), succ, fail, canc)
449	}
450	
451	// formatDuration formats a duration compactly for the table column.
452	func formatDuration(d time.Duration) string {
453		if d < time.Second {
454			return fmt.Sprintf("%dms", d.Milliseconds())
455		}
456		if d < time.Minute {
457			return fmt.Sprintf("%.1fs", d.Seconds())
458		}
459		return fmt.Sprintf("%dm%ds", int(d.Minutes()), int(d.Seconds())%60)
460	}
461	
462	// formatCompact formats a token count as e.g. "1.2k" or "450".
463	func formatCompact(n int) string {
464		if n >= 1000 {
465			return fmt.Sprintf("%.1fk", float64(n)/1000)
466		}
467		return strconv.Itoa(n)
468	}
